import http from 'node:http';
import { parse as parseUrl } from 'node:url';

export class Response {
  constructor(body, options = {}) {
    this.body = body;
    this.status = options.status || 200;
    this.contentType = options.contentType || 'application/json';
    this.headers = options.headers || {};
  }
}

export class SidecarApp {
  constructor() {
    this.routes = [];
    this.config = {
      conversationId: process.env.ANTIGRAVITY_CONVERSATION_ID || '',
    };
    this.port = parseInt(process.env.PORT || '4820', 10);
    this.server = null;
  }

  page(path, handler) {
    this.routes.push({
      method: 'GET',
      path,
      type: 'page',
      handler,
    });
  }

  api(path, handler, method = 'GET') {
    this.routes.push({
      method: method.toUpperCase(),
      path,
      type: 'api',
      handler,
    });
  }

  run() {
    this.server = http.createServer((req, res) => {
      res.setHeader('Access-Control-Allow-Origin', '*');
      res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
      res.setHeader('Access-Control-Allow-Headers', '*');

      if (req.method === 'OPTIONS') {
        res.writeHead(204);
        res.end();
        return;
      }

      const parsed = parseUrl(req.url, true);
      const pathname = parsed.pathname;
      const query = parsed.query;

      if (pathname === '/preload.js') {
        res.writeHead(200, { 'Content-Type': 'application/javascript' });
        res.end('// Browser standalone shim\nwindow.sidecar = window.sidecar || {};\n');
        return;
      }

      const route = this.routes.find(
        (r) => r.method === req.method && r.path === pathname
      );

      if (!route) {
        res.writeHead(404, { 'Content-Type': 'text/plain' });
        res.end('Not Found');
        return;
      }

      try {
        if (route.type === 'page') {
          const html = route.handler();
          res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
          res.end(html);
        } else {
          const result = route.handler(query);
          if (result instanceof Response) {
            const headers = {
              'Content-Type': result.contentType,
              ...result.headers,
            };
            res.writeHead(result.status, headers);
            res.end(result.body);
          } else if (result && typeof result === 'object') {
            res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
            res.end(JSON.stringify(result));
          } else {
            res.writeHead(200);
            res.end(result);
          }
        }
      } catch (err) {
        console.error(`[SidecarApp] Error handling ${pathname}:`, err);
        res.writeHead(500, { 'Content-Type': 'text/plain' });
        res.end(err.message);
      }
    });

    this.server.listen(this.port, '0.0.0.0', () => {
      console.log(`[Swarm Dashboard] Listening on http://127.0.0.1:${this.port}/`);
    });
  }
}
